const request = $input.first().json;
const headers = request.headers || {};
const body = request.body || request;
const providedSecret = String(headers['x-buma-secret'] || '');
const expectedSecret = String($env.N8N_SHARED_SECRET || '');
const required = ['order_id', 'action', 'sender_email', 'subject', 'draft_reply', 'status'];
const missing = required.filter((key) => !String(body[key] ?? '').trim());
let valid = true;
let http_status = 200;
let error = '';
if (!expectedSecret || providedSecret !== expectedSecret) {
  valid = false;
  http_status = 403;
  error = 'Invalid shared secret';
} else if (missing.length) {
  valid = false;
  http_status = 400;
  error = 'Missing fields: ' + missing.join(', ');
} else if (body.action !== 'approve') {
  valid = false;
  http_status = 400;
  error = 'Unsupported action';
}
const idempotency_key = String(headers['x-idempotency-key'] || body.idempotency_key || '').trim();
if (valid && !idempotency_key) {
  valid = false;
  http_status = 400;
  error = 'Missing idempotency key';
}
return [{ json: { ...body, valid, http_status, error, idempotency_key, test_mode: body.test_mode === true } }];

const request = $('Validate secret and payload').first().json;
const rows = $input.all().map((item) => item.json || {}).filter((row) => Object.keys(row).length > 0);
const requestedId = String(request.order_id || '').trim();
const stored = rows.find((row) => String(row.order_id || row.id || '').trim() === requestedId);
let valid = true;
let http_status = 200;
let error = '';
if (!stored) {
  valid = false;
  http_status = 404;
  error = 'Order was not found in FIT Inbound Emails';
}
const storedDecision = String(stored?.decision || '').trim().toLowerCase();
const storedStatus = String(stored?.status || '').trim().toLowerCase();
const gmail_message_id = String(stored?.gmail_message_id || stored?.inbound_message_id || stored?.message_id || '').trim();
if (valid && storedDecision !== 'review_required') {
  valid = false;
  http_status = 409;
  error = 'Stored decision ' + (storedDecision || 'missing') + ' cannot be approved';
}
if (valid && ['sent', 'poslano', 'email_sent'].includes(storedStatus)) {
  valid = false;
  http_status = 409;
  error = 'Order is already marked as sent';
}
if (valid && !gmail_message_id) {
  valid = false;
  http_status = 409;
  error = 'Trusted Gmail message id is missing';
}
return [{ json: {
  ...request,
  valid,
  http_status,
  error,
  sender_email: String(stored?.sender_email || stored?.sender || request.sender_email || ''),
  subject: String(stored?.subject || request.subject || ''),
  decision: storedDecision,
  status: storedStatus,
  thread_id: String(stored?.thread_id || ''),
  gmail_message_id,
  lookup_verified: Boolean(stored),
  decision_validated: valid
} }];

const item = $input.first().json;
const store = $getWorkflowStaticData('global');
store.approveKeys = store.approveKeys || {};
const dedupe_key = (item.test_mode ? 'test' : 'live') + ':' + item.idempotency_key;
const previous = store.approveKeys[dedupe_key];
const duplicate = Boolean(previous);
if (!duplicate) {
  store.approveKeys[dedupe_key] = { status: 'pending', created_at: new Date().toISOString() };
}
return [{ json: {
  ...item,
  dedupe_key,
  duplicate,
  duplicate_status: String(previous?.status || ''),
  duplicate_email_sent: previous?.status === 'sent'
} }];

const item = $input.first().json;
const store = $getWorkflowStaticData('global');
store.approveKeys[item.dedupe_key] = { status: 'dry_run', created_at: new Date().toISOString() };
return [{ json: {
  success: true,
  status: 'dry_run',
  test_mode: true,
  email_sent: false,
  lookup_verified: item.lookup_verified === true,
  decision_validated: item.decision_validated === true,
  idempotency_key: item.idempotency_key
} }];

const request = $('Idempotency gate').first().json;
const gmail = $input.first().json;
const message_id = String(gmail.id || gmail.messageId || gmail.message_id || '');
const sent_at = new Date().toISOString();
const store = $getWorkflowStaticData('global');
store.approveKeys[request.dedupe_key] = { status: 'sent', sent_at, message_id };
return [{ json: { success: true, status: 'sent', test_mode: false, email_sent: true, sent_at, message_id, idempotency_key: request.idempotency_key } }];

const request = $('Idempotency gate').first().json;
const failure = $input.first().json;
const send_error = String(failure.error?.message || failure.message || failure.error || 'Gmail send failed').slice(0, 2000);
const store = $getWorkflowStaticData('global');
store.approveKeys[request.dedupe_key] = { status: 'send_error', send_error, failed_at: new Date().toISOString() };
return [{ json: { success: false, status: 'send_error', test_mode: false, email_sent: false, send_error, idempotency_key: request.idempotency_key } }];
